public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n < 0) throw new IllegalArgumentException("n must be non-negative");
    if (start == null || end == null) throw new IllegalArgumentException("start and end cannot be null");
    if (start.length != n || end.length != n) throw new IllegalArgumentException("start and end length must equal n");
    if (paths == null) throw new IllegalArgumentException("paths cannot be null");
    java.util.function.Function<int[], String> coordToKey = coord -> {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);
    if (startKey.equals(endKey)) return "can be travelled";
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * n) continue;
        int[] coord1 = java.util.Arrays.copyOfRange(path, 0, n);
        int[] coord2 = java.util.Arrays.copyOfRange(path, n, 2 * n);
        String key1 = coordToKey.apply(coord1);
        String key2 = coordToKey.apply(coord2);
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.get(current);
        if (neighbors == null) continue;
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                if (neighbor.equals(endKey)) return "can be travelled";
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

