    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple) {
    int total = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int childTotal = dfs(child, node, graph, hasApple);
        if (childTotal > 0 || hasApple[child]) {
            total += childTotal + 2;
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int n = s.length();
    if (n == 0) {
        return "";
    }
    // Frequency array for all possible char values (Unicode BMP)
    int[] freq = new int[65536];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder result = new StringBuilder(n);
    int remaining = n;

    while (remaining > 0) {
        // Ascending pass
        int last = -1;
        for (int c = 0; c < 65536; c++) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
                last = c;
                break;
            }
        }
        if (remaining == 0) {
            break;
        }
        for (int c = last + 1; c < 65536; c++) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
                last = c;
            }
        }
        if (remaining == 0) {
            break;
        }

        // Descending pass
        for (int c = 65535; c >= 0; c--) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
                last = c;
                break;
            }
        }
        if (remaining == 0) {
            break;
        }
        for (int c = last - 1; c >= 0; c--) {
            if (freq[c] > 0) {
                result.append((char) c);
                freq[c]--;
                remaining--;
                last = c;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    long totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] dp = new HashSet[n + 1];
    dp[0] = new HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        // iterate k from high to low to avoid using updated values in the same iteration
        for (int k = n - 1; k >= 1; k--) {
            if (dp[k - 1] == null) continue;
            if (dp[k] == null) dp[k] = new HashSet<>();
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    // Check for any valid subset size k
    for (int k = 1; k <= n / 2; k++) {
        long targetLong = totalSum * k;
        if (targetLong % n != 0) continue;
        int target = (int) (targetLong / n);
        if (dp[k] != null && dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dp[i - 1] + cost[i - 1];
        int costFromPrevPrev = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(costFromPrev, costFromPrevPrev);
    }
    return dp[n];
}

