public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return false;
    int n = s.length();
    if (n < k) return false;
    if (k > 20) return false; // too large to handle within int limits
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int val = 0;
    int mask = total - 1;
    for (int i = 0; i < n; i++) {
        val = ((val << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                seenCount++;
                if (seenCount == total) return true;
            }
        }
    }
    return false;
}

