    for (String log : logs) {
        if (log == null) {
            continue; // skip null entries
        }
        if (log.equals("../")) {
            if (depth > 0) {
                depth--;
            }
        } else if (log.equals("./")) {
            // stay in the current folder, no change
        } else if (log.endsWith("/") && !log.equals("../") && !log.equals("./")) {
            depth++;
        } else {
            // ignore any malformed log entry
        }
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }
    int minSum = n;          // all 'a'
    int maxSum = 26 * n;     // all 'z'
    if (k < minSum || k > maxSum) {
        throw new IllegalArgumentException("k is out of valid range");
    }
    char[] result = new char[n];
    // start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - minSum; // how much we need to add
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

