public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array is null or empty");
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        int sum = 0;
        for (int num : nums) {
            sum += (num >> i) & 1;
        }
        if ((sum % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    // Handle 0 separately
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is positive and has exactly one bit set.
    // For n > 0, n & (n - 1) will be zero only for powers of two.
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], anti[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }
    boolean negative = n < 0;
    // Use long to safely handle Integer.MIN_VALUE
    long absVal = Math.abs((long) n);
    String numStr = Long.toString(absVal);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) return 0;
    int n = A.length;
    if (n == 0) return 1;
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    // Precompute perfect squares up to max sum
    int maxVal = A[n - 1];
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 1; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    // DP memoization: dp[mask][lastIndex+1]
    int[][] dp = new int[1 << n][n + 1];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1);
    }
    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int mask, int last) {
            int key = mask * (n + 1) + (last + 1);
            if (dp[mask][last + 1] != -1) return dp[mask][last + 1];
            if (mask == (1 << n) - 1) {
                return dp[mask][last + 1] = 1;
            }
            long count = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;
                if (last != -1 && !isSquare[A[i] + A[last]]) continue;
                count += applyAsInt(mask | (1 << i), i);
                if (count > Integer.MAX_VALUE) count = Integer.MAX_VALUE; // prevent overflow
            }
            return dp[mask][last + 1] = (int) count;
        }
    };
    return dfs.applyAsInt(0, -1);
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    while (top >= 0) {
        int height = heights[stack[top--]];
        int width = (top == -1) ? n : n - stack[top] - 1;
        long area = (long) height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    int maxSum = m + n - 2;
    for (int sum = 0; sum <= maxSum; sum++) {
        int startRow, startCol;
        if (sum % 2 == 0) {
            // even sum: traverse from bottom to top
            startRow = Math.min(sum, m - 1);
            startCol = sum - startRow;
        } else {
            // odd sum: traverse from top to bottom
            startCol = Math.min(sum, n - 1);
            startRow = sum - startCol;
        }
        int r = startRow;
        int c = startCol;
        while (r >= 0 && r < m && c >= 0 && c < n) {
            result[idx++] = mat[r][c];
            if (sum % 2 == 0) {
                r--; // move up
                c++; // move right
            } else {
                r++; // move down
                c--; // move left
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[] arr = new char[n];
    build(0, n - 1, arr, result, n);
    return result;
}

private static void build(int l, int r, char[] arr, List<String> result, int n) {
    if (l > r) {
        result.add(new String(arr));
        return;
    }
    if (l == r) {
        char[] mids = {'0', '1', '8'};
        for (char c : mids) {
            arr[l] = c;
            result.add(new String(arr));
        }
        return;
    }
    char[][] pairs = {{'0','0'},{'1','1'},{'8','8'},{'6','9'},{'9','6'}};
    for (char[] p : pairs) {
        if (l == 0 && n > 1 && p[0] == '0') {
            continue;
        }
        arr[l] = p[0];
        arr[r] = p[1];
        build(l + 1, r - 1, arr, result, n);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for null subarrays and duplicate points
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Ensure all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    // Compute cross product to check collinearity
    long x1 = points[0][0], y1 = points[0][1];
    long x2 = points[1][0], y2 = points[1][1];
    long x3 = points[2][0], y3 = points[2][1];
    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) next;
        if (next == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2;
        }
        if (next == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3;
        }
        if (next == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    char prev = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == prev) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
            prev = c;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long current = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    // Helper to check perfect square
    java.util.function.IntPredicate isSquare = (int x) -> {
        int r = (int) Math.sqrt(x);
        return r * r == x;
    };
    // 1. Check if n itself is a perfect square
    if (isSquare.test(n)) {
        return 1;
    }
    // 2. Check if n can be expressed as sum of two perfect squares
    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        int remainder = n - i * i;
        if (remainder >= 0 && isSquare.test(remainder)) {
            return 2;
        }
    }
    // 3. Legendre's three-square theorem: if n is of the form 4^a*(8b+7), answer is 4
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 == 7) {
        return 4;
    }
    // 4. Otherwise, answer is 3
    return 3;
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            result.append(word.reverse());
            word.setLength(0);
            result.append(c);
        }
    }
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
